    ("shield-makes-outer-uncancellable", "asyncio.shield prevents the outer caller from being cancelled", "Shield blocks that outer cancellation path into the protected inner task. The outer await can still raise CancelledError, and a separate cancellation of the inner task remains possible.", "shield-await"),
    ("wait-for-is-hard-deadline", "wait_for always raises TimeoutError at its exact deadline", "CPython 3.14.7 can continue waiting while the child handles cancellation and cleans up. If the child suppresses that cancellation and returns a value, wait_for can return that value instead of raising TimeoutError.", "wait-for-timeout"),
    ("bounded-queue-bounds-memory", "A bounded queue bounds all memory used by its pipeline", "Positive asyncio maxsize bounds queued item count. Payload sizes, already-dequeued work, producer-local values, and separately spawned waiting tasks can retain additional memory outside that count.", "bounded-queue"),
